"""Evaluate PDF retrieval and answer checks using a reviewed JSON question set."""
import argparse
import json
import re
import subprocess
import sys
import time
from pathlib import Path

from ingestion.generate_captions import safe_error


def load_cases(path, allow_unreviewed=False):
    """Ground truth must be supplied/reviewed by a human, not generated by the RAG."""
    dataset = json.loads(Path(path).read_text(encoding="utf-8"))
    cases = dataset["cases"]
    if not cases or len({c["id"] for c in cases}) != len(cases):
        raise ValueError("Dataset needs nonempty cases with unique IDs")
    for case in cases:
        if not isinstance(case["question"], str) or not case["question"].strip():
            raise ValueError("Each case needs a question")
        if not isinstance(case.get("answerable"), bool):
            raise ValueError("Each case needs a boolean answerable")
        if not case.get("reviewed") and not allow_unreviewed:
            raise ValueError(f"Review case {case['id']} and mark reviewed=true, or use --allow-unreviewed for a draft run")
        if case.get("content_type") not in (None, "text", "image", "table"):
            raise ValueError("Invalid content_type")
        for field in ("expected_pages", "expected_record_ids", "expected_image_paths", "answer_contains_all"):
            if not isinstance(case.get(field, []), list):
                raise ValueError(f"{field} must be a list")
        if not all(isinstance(p, int) and p > 0 for p in case.get("expected_pages", [])):
            raise ValueError("Expected pages must be one-based positive integers")
        if case["answerable"] and not (case.get("expected_pages") or case.get("expected_record_ids")):
            raise ValueError("Answerable cases need expected pages or record IDs")
    return cases


def score_case(case, retrieved, answer=None):
    """Compute evidence metrics; word checks are proxies, not factual grading."""
    if retrieved["question"] != case["question"]:
        raise ValueError("Retrieval question does not match dataset")
    hits = retrieved["results"]
    pages = set(case.get("expected_pages", []))
    ids = set(case.get("expected_record_ids", []))
    relevant = [bool((ids and h["record_id"] in ids) or (not ids and h["page_number"] in pages)) for h in hits]
    metrics = {}
    if case["answerable"]:
        metrics["hit_at_k"] = any(relevant)
        metrics["reciprocal_rank"] = next((1 / (i + 1) for i, value in enumerate(relevant) if value), 0)
        if pages:
            metrics["expected_page_recall"] = len(pages & {h["page_number"] for h in hits}) / len(pages)
        if ids:
            metrics["expected_record_recall"] = len(ids & {h["record_id"] for h in hits}) / len(ids)
    if answer is not None:
        if answer["question"] != case["question"]:
            raise ValueError("Answer question does not match dataset")
        sources = answer["sources"]
        hit_ids = {h["record_id"] for h in hits}
        metrics["cited_ids_from_retrieval"] = all(s["record_id"] in hit_ids for s in sources)
        declared = {s["label"] for s in sources}
        inline = set(re.findall(r"\[(S\d+)\]", answer["answer"]))
        metrics["inline_citations_valid"] = inline <= declared
        if case["answerable"]:
            metrics["has_sources"] = bool(sources)
            metrics["has_inline_citations"] = bool(inline)
            good_ids = {h["record_id"] for h, good in zip(hits, relevant) if good}
            metrics["cites_expected_evidence"] = any(s["record_id"] in good_ids for s in sources)
            phrases = case.get("answer_contains_all", [])
            if phrases:
                text = " ".join(answer["answer"].casefold().split())
                metrics["answer_phrase_check"] = all(" ".join(p.casefold().split()) in text for p in phrases)
            expected_images = case.get("expected_image_paths", [])
            if expected_images:
                returned = [Path(i["image_path"]).as_posix() for i in answer["images"]]
                metrics["expected_image_selected"] = any(
                    actual.endswith("/" + Path(expected).as_posix()) or actual == Path(expected).as_posix()
                    for actual in returned for expected in expected_images)
        else:
            # Empty sources alone do not establish that the wording is a refusal.
            metrics["unsupported_no_sources_or_images"] = not sources and not answer["images"]
    return metrics


def summarize(results):
    names = {key for row in results for key in row.get("metrics", {})}
    metrics = {}
    for name in sorted(names):
        values = [row["metrics"][name] for row in results if name in row.get("metrics", {})]
        metrics[name] = {"mean": sum(values) / len(values), "evaluated_cases": len(values)}
    return {"completed": sum(r["status"] == "completed" for r in results),
            "errors": sum(r["status"] == "error" for r in results), "metrics": metrics}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("dataset", nargs="?", type=Path, default=Path(__file__).with_name("evaluation_cases.json"))
    parser.add_argument("--output-dir", type=Path, default=Path("evaluation_results"))
    parser.add_argument("--prepared", type=Path)
    parser.add_argument("--evidence-root", type=Path)
    parser.add_argument("--checkpoint", type=Path)
    parser.add_argument("--top-k", type=int, default=5)
    parser.add_argument("--retrieval-only", action="store_true")
    parser.add_argument("--allow-unreviewed", action="store_true")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--limit", type=int)
    parser.add_argument("--interval", type=float, default=15)
    parser.add_argument("--timeout", type=float, default=300)
    parser.add_argument("--cached", action="store_true", help="Score previously saved outputs without API calls")
    args = parser.parse_args()
    try:
        if not 1 <= args.top_k <= 100 or args.interval < 0 or args.timeout <= 0 or (args.limit is not None and args.limit < 1):
            raise ValueError("Invalid top-k, interval, timeout, or limit")
        cases = load_cases(args.dataset, args.allow_unreviewed)
        if args.limit:
            cases = cases[:args.limit]
        if args.dry_run:
            print(f"Validated {len(cases)} cases; {sum(not c.get('reviewed', False) for c in cases)} unreviewed. No API calls.")
            return
        directory = args.output_dir.resolve()
        directory.mkdir(parents=True, exist_ok=True)
        if not args.cached and any(directory.iterdir()):
            raise ValueError("Use a new output directory, or --cached to score saved results")
        results = []
        for index, case in enumerate(cases, 1):
            row = {"id": case["id"], "question": case["question"], "reviewed": bool(case.get("reviewed")),
                   "status": "completed", "human_review": {"answer_correct": None, "citations_support_claims": None,
                                                            "image_subject_correct": None, "unsupported_refusal_correct": None}}
            # Numbered filenames prevent dataset IDs from escaping the output folder.
            retrieval_path = directory / f"case_{index:03d}_retrieval.json"
            answer_path = directory / f"case_{index:03d}_answer.json"
            try:
                if not args.cached:
                    if index > 1:
                        time.sleep(args.interval)
                    command = [sys.executable, "-m", "rag.retrieve_documents",
                               case["question"], "--top-k", str(args.top_k), "--output", str(retrieval_path)]
                    if case.get("content_type"):
                        command.extend(["--type", case["content_type"]])
                    for option in ("prepared", "evidence_root", "checkpoint"):
                        if getattr(args, option):
                            command.extend(["--" + option.replace("_", "-"), str(getattr(args, option))])
                    run_command(command, args.timeout)
                    if not args.retrieval_only:
                        run_command([sys.executable, "-m", "rag.answer_question",
                                     case["question"], "--retrieved", str(retrieval_path), "--output", str(answer_path)], args.timeout)
                retrieved = json.loads(retrieval_path.read_text(encoding="utf-8"))
                answer = None if args.retrieval_only else json.loads(answer_path.read_text(encoding="utf-8"))
                row["metrics"] = score_case(case, retrieved, answer)
                row["retrieval_path"] = str(retrieval_path)
                row["answer_path"] = str(answer_path) if answer else None
            except Exception as exc:
                row.update(status="error", error=safe_error(exc))
            results.append(row)
            report = {"dataset": str(args.dataset.resolve()), "top_k": args.top_k,
                      "draft": any(not c.get("reviewed") for c in cases),
                      "limitations": "Page hits and phrase checks do not prove correctness. Human review required.",
                      "summary": summarize(results), "cases": results}
            (directory / "report.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
            print(f"{index}/{len(cases)} {case['id']}: {row['status']}", flush=True)
        print(json.dumps(summarize(results), indent=2))
        print(f"Report: {directory / 'report.json'}")
        if any(r["status"] == "error" for r in results):
            parser.exit(1, "Some cases failed; see report.json.\n")
    except Exception as exc:
        parser.exit(1, f"Evaluation failed: {safe_error(exc)}\n")


def run_command(command, timeout):
    result = subprocess.run(command, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout)
    if result.returncode:
        raise RuntimeError(result.stderr or result.stdout)


if __name__ == "__main__":
    main()
